import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"تین سو سیٹ سادھن سسٹم کا اشاریہ","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0091-三百套修炼体系索引.md","filePath":"ur/0091-三百套修炼体系索引.md"}'),h={name:"ur/0091-三百套修炼体系索引.md"};function o(l,t,i,b,n,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="تین-سو-سیٹ-سادھن-سسٹم-کا-اشاریہ" tabindex="-1">تین سو سیٹ سادھن سسٹم کا اشاریہ <a class="header-anchor" href="#تین-سو-سیٹ-سادھن-سسٹم-کا-اشاریہ" aria-label="Permalink to &quot;تین سو سیٹ سادھن سسٹم کا اشاریہ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>91</td></tr><tr><td>ماڈیول</td><td>ضمیمے اور حوالہ جات</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>تین سو سیٹ سسٹم، سادھن اشاریہ، چھ بڑی اقسام، سسٹم نمبر، اصلی سادھن</td></tr></tbody></table><h2 id="_1-اشاریے-کی-وضاحت" tabindex="-1">1. اشاریے کی وضاحت <a class="header-anchor" href="#_1-اشاریے-کی-وضاحت" aria-label="Permalink to &quot;1. اشاریے کی وضاحت&quot;">​</a></h2><p>اس اشاریے میں اینکر سمبیوسس تہذیب کی طرف سے کھولے گئے تمام تین سو سیٹ کائناتی اصلی سادھن سسٹم شامل ہیں، جنہیں چھ بڑی اقسام میں ترتیب دیا گیا ہے، ہر قسم میں پچاس سیٹ، نمبر 001 سے 300 تک مسلسل ترتیب دیے گئے ہیں۔ پہلے تین سیٹ سسٹم (تخمینہ تکرار، زندگی چکر، مقامی قانون کنٹرول) &quot;اصل تین بنیادیں&quot; ہیں، جو تمام سسٹموں کی سادھن کی بنیاد ہیں۔ ہر سیٹ سسٹم میں نمبر، نام اور بنیادی سمت کا مختصر خلاصہ درج ہے۔ یہ اشاریہ ایک مشورتی آلہ ہے؛ ہر سسٹم کی تفصیلی سادھن طریقہ اور درجوں کی تقسیم کے لیے متعلقہ سسٹم کی خصوصی دستاویز دیکھیں۔</p><h2 id="_2-اصل-تخمینہ-کی-قسم-سیٹ-001-050" tabindex="-1">2. اصل تخمینہ کی قسم (سیٹ 001-050) <a class="header-anchor" href="#_2-اصل-تخمینہ-کی-قسم-سیٹ-001-050" aria-label="Permalink to &quot;2. اصل تخمینہ کی قسم (سیٹ 001-050)&quot;">​</a></h2><p>اصل تخمینہ کی قسم کے سسٹم تخمینہ، حساب اور تکرار کو بنیاد کے طور پر لیتے ہیں، ذہین قسم اور تحقیقی قسم کی زندگی کی سادھن کے لیے موزوں ہیں، اور منطقی تخمینہ اور مسلسل تکرار کے ذریعے کائناتی اصل تک پہنچنے پر زور دیتے ہیں۔</p><table tabindex="0"><thead><tr><th>نمبر</th><th>سسٹم کا نام</th><th>بنیادی سمت</th></tr></thead><tbody><tr><td>001</td><td>تخمینہ تکرار سسٹم</td><td>سو گنا تخمینہ اضافہ، تخمینہ تصدیق تکرار کے ذریعے سادھن کے راستے کی بہتری (اصل تین بنیادیوں میں سے ایک)</td></tr><tr><td>002</td><td>وجہ و نتیجہ تخمینہ فن</td><td>وجہ و نتیجہ کے قوانین کو تخمینے کے موضوع کے طور پر لیتا ہے، واقعات کی وجہ اور نتیجہ کا پتہ لگاتا ہے</td></tr><tr><td>003</td><td>عددی اصلی الگورتھم</td><td>کائناتی قوانین کو ریاضیاتی ماڈل میں تبدیل کر کے تخمینہ اور حساب کرتا ہے</td></tr><tr><td>004</td><td>منطقی بند چکر کی تکنیک</td><td>منطقی خود مطابقت کو سادھن کی بنیاد کے طور پر لیتا ہے، بے عیب فکر کا نظام بناتا ہے</td></tr><tr><td>005</td><td>امکانی تخمینہ راستہ</td><td>مستقبل کے واقعات کی امکانی تقسیم کا تخمینہ کرتا ہے، امکانات میں بہترین راستہ تلاش کرتا ہے</td></tr><tr><td>006</td><td>وقت کی لائن تخمینہ طریقہ</td><td>مختلف وقت کی لائنوں کی شاخوں کا تخمینہ اور موازنہ کرتا ہے، بہترین ارتقاء کی سمت کا انتخاب کرتا ہے</td></tr><tr><td>007</td><td>قانون کی تخریب تخمینہ فن</td><td>پیچیدہ قوانین کو بنیادی اجزاء میں تقسیم کر کے تجزیہ اور تخمینہ کرتا ہے</td></tr><tr><td>008</td><td>کثیر جہتی تخمینہ کی تکنیک</td><td>کثیر جہتی جگہ میں بیک وقت متعدد سادھن راستوں کا تخمینہ کرتا ہے</td></tr><tr><td>009</td><td>تکراری تکرار راستہ</td><td>تکراری الگورتھم کو بنیاد کے طور پر لیتا ہے، سطح در سطح گہرائی تک جا کر اصل تک پہنچتا ہے</td></tr><tr><td>010</td><td>تخمینہ طریقہ کی نقل</td><td>شعور میں مکمل کائناتی ماڈل بنا کر تخمینہ کی نقل کرتا ہے</td></tr><tr><td>011</td><td>کھیل کے نظریے کی تخمینہ فن</td><td>کثیر فریقین کے کھیل کے ماڈل کی بنیاد پر بہترین حکمت عملی کا تخمینہ کرتا ہے</td></tr><tr><td>012</td><td>افراتفری تخمینہ کی تکنیک</td><td>افراتفری کے نظام میں پوشیدہ ترتیب اور قواعد تلاش کرتا ہے</td></tr><tr><td>013</td><td>ٹوپولوجی تخمینہ راستہ</td><td>ٹوپولوجی کو ایک آلے کے طور پر استعمال کر کے مقامی قانون کی جگہ کی ساختی خصوصیات کا تجزیہ کرتا ہے</td></tr><tr><td>014</td><td>معلومات تخمینہ طریقہ</td><td>معلومات کے نظریے کے طریقے کے ذریعے معلومات کے ارتقاء اور منتقلی کے قواعد کا تخمینہ کرتا ہے</td></tr><tr><td>015</td><td>کوانٹم تخمینہ فن</td><td>کوانٹم میکانکس کے اصولوں کی بنیاد پر خرد سطح کے قانونی تخمینہ کرتا ہے</td></tr><tr><td>016</td><td>سسٹم تخمینہ کی تکنیک</td><td>سسٹم کے نظریے کو ایک فریم ورک کے طور پر استعمال کر کے پیچیدہ سسٹم کے ارتقاء کے قواعد کا تخمینہ کرتا ہے</td></tr><tr><td>017</td><td>سائبرنیٹکس تخمینہ راستہ</td><td>سائبرنیٹکس کے طریقے کے ذریعے سادھن کے عمل کے بہترین کنٹرول حکمت عملی کا تخمینہ کرتا ہے</td></tr><tr><td>018</td><td>نیٹ ورک تخمینہ طریقہ</td><td>نیٹ ورک سائنس کو ایک آلے کے طور پر استعمال کر کے سمبیوسس نیٹ ورک کے ارتقاء کے قواعد کا تخمینہ کرتا ہے</td></tr><tr><td>019</td><td>فریکٹل تخمینہ فن</td><td>فریکٹل جیومیٹری کے اصولوں کا استعمال کر کے کائناتی قوانین کی خود مماثل ساخت کا تخمینہ کرتا ہے</td></tr><tr><td>020</td><td>اینٹروپی تخمینہ کی تکنیک</td><td>تھرموڈینامکس کے اینٹروپی قانون کو بنیاد کے طور پر لے کر کائناتی ارتقاء کی حتمی سمت کا تخمینہ کرتا ہے</td></tr><tr><td>021</td><td>پیراڈوکس تخمینہ راستہ</td><td>منطقی پیراڈوکس کا مطالعہ کر کے روایتی فکر کی حدود کو عبور کرتا ہے</td></tr><tr><td>022</td><td>میٹا تخمینہ طریقہ</td><td>خود تخمینے کا تخمینہ کرتا ہے، میٹا شعور کی سطح کا ارتقاء حاصل کرتا ہے</td></tr><tr><td>023</td><td>سپر کمپیوٹنگ تخمینہ فن</td><td>سادھن کی شعور کو سپر کمپیوٹنگ انجن میں تبدیل کر کے بڑے پیمانے پر تخمینہ کرتا ہے</td></tr><tr><td>024</td><td>متوازی تخمینہ کی تکنیک</td><td>بیک وقت لاکھوں سادھن راستوں کا متوازی تخمینہ کرتا ہے، بہترین کا انتخاب کرتا ہے</td></tr><tr><td>025</td><td>الٹا تخمینہ راستہ</td><td>ہدف کی حالت سے الٹا طریقے سے پہنچنے کے راستے کی سادھن طریقہ کا تخمینہ کرتا ہے</td></tr><tr><td>026</td><td>مکمل تخمینہ طریقہ</td><td>کسی خاص قانونی شعبے میں مکمل تخمینہ کرتا ہے، کوئی کونہ نہیں چھوڑتا</td></tr><tr><td>027</td><td>ہیورسٹک تخمینہ فن</td><td>ہیورسٹک الگورتھم کا استعمال کر کے بہت بڑے حل کی جگہ میں جلدی قریب ترین بہترین حل تلاش کرتا ہے</td></tr><tr><td>028</td><td>جینیٹک تخمینہ کی تکنیک</td><td>حیاتیاتی جینیٹک ارتقاء کے طریقہ کار کی نقل کرتا ہے، انتخاب کراس اوور میوٹیشن کے ذریعے سادھن کے راستے کی بہتری کرتا ہے</td></tr><tr><td>029</td><td>نیورل نیٹ ورک تخمینہ راستہ</td><td>مصنوعی نیورل نیٹ ورک کو ماڈل کے طور پر استعمال کر کے سادھن کی شعور کی گہری سیکھنے کی صلاحیت بناتا ہے</td></tr><tr><td>030</td><td>مبہم تخمینہ طریقہ</td><td>نامکمل معلومات کی حالت میں مبہم منطقی تخمینہ کرتا ہے</td></tr><tr><td>031</td><td>وجدان تخمینہ فن</td><td>منطقی تخمینہ کو وجدان کے ادراک کے ساتھ جوڑتا ہے، چھلانگ لگانے والی شعوری کامیابی حاصل کرتا ہے</td></tr><tr><td>032</td><td>جدلیاتی تخمینہ کی تکنیک</td><td>مادیت پسندانہ جدلیات کا استعمال کر کے تضاد کے دونوں فریقین کی تبدیلی اور اتحاد کا تخمینہ کرتا ہے</td></tr><tr><td>033</td><td>فینومینالوجی تخمینہ راستہ</td><td>فینومینالوجی کمی کے طریقے کے ذریعے قانون کی اصلی پیش کش کا سامنا کرتا ہے</td></tr><tr><td>034</td><td>ساختیات تخمینہ طریقہ</td><td>ساختیات کے طریقے کے ذریعے قانونی سسٹم کی گہری ساخت کا تجزیہ کرتا ہے</td></tr><tr><td>035</td><td>تخریب تخمینہ فن</td><td>موجودہ سادھن سسٹم کی تخریب کرتا ہے، پوشیدہ نئے راستے دریافت کرتا ہے</td></tr><tr><td>036</td><td>تعمیر تخمینہ کی تکنیک</td><td>تخریب کی بنیاد پر دوبارہ زیادہ کامل سادھن سسٹم بناتا ہے</td></tr><tr><td>037</td><td>تقابلی تخمینہ راستہ</td><td>مختلف سسٹموں کے فوائد اور نقصانات کی افقی تقابل کے ذریعے اپنی سادھن کی بہتری کرتا ہے</td></tr><tr><td>038</td><td>تاریخی تخمینہ طریقہ</td><td>سادھن کی تاریخ کی تاریخی ارتقاء سے مستقبل کی ترقی کی سمت کا تخمینہ کرتا ہے</td></tr><tr><td>039</td><td>بین الضابطہ تخمینہ فن</td><td>متعدد مضامین کے علم کو یکجا کر کے سرحد پار تخمینہ کرتا ہے، جدت کو متحرک کرتا ہے</td></tr><tr><td>040</td><td>انتہائی تخمینہ کی تکنیک</td><td>انتہائی حالات میں قانون کی انتہائی کارکردگی اور حدود کا تخمینہ کرتا ہے</td></tr><tr><td>041</td><td>سب سے سادہ تخمینہ راستہ</td><td>سب سے سادہ ماڈل سے سب سے پیچیدہ قانونی واقعات کی وضاحت کرنے کی کوشش کرتا ہے</td></tr><tr><td>042</td><td>مکمل تخمینہ طریقہ</td><td>تخمینہ سسٹم کی مکمل ہونے کی کوشش کرتا ہے، یقینی بناتا ہے کہ کوئی امکان چھوٹا نہ جائے</td></tr><tr><td>043</td><td>مطابقت تخمینہ فن</td><td>تخمینہ سسٹم کی اندرونی منطقی مطابقت کی جانچ کرتا ہے، تضاد دور کرتا ہے</td></tr><tr><td>044</td><td>آزادی تخمینہ کی تکنیک</td><td>سادھن سسٹم میں ہر بنیادی مفروضے کی آزادی کا تخمینہ کرتا ہے</td></tr><tr><td>045</td><td>فیصلہ قابل تخمینہ راستہ</td><td>قانونی مسائل کی فیصلہ قابلیت کا مطالعہ کرتا ہے، حل قابل اور ناقابل حل مسائل کو الگ کرتا ہے</td></tr><tr><td>046</td><td>پیچیدگی تخمینہ طریقہ</td><td>قانونی مسائل کی کمپیوٹنگ پیچیدگی کا تجزیہ کرتا ہے، تخمینہ کی کارکردگی کو بہتر بناتا ہے</td></tr><tr><td>047</td><td>قریبی تخمینہ فن</td><td>جب درست حل دستیاب نہ ہو تو اعلیٰ معیار کا قریبی حل تلاش کرتا ہے</td></tr><tr><td>048</td><td>بے ترتیب تخمینہ کی تکنیک</td><td>بے ترتیبی متعارف کروا کر مونٹی کارلو طرز کی تخمینہ کرتا ہے، نامعلوم علاقوں کی تلاش کرتا ہے</td></tr><tr><td>049</td><td>تعاون تخمینہ راستہ</td><td>متعدد سادھن کاروں کی شعور تعاون کر کے بڑے پیمانے پر تقسیم شدہ تخمینہ کرتا ہے</td></tr><tr><td>050</td><td>اصل یکجا تخمینہ طریقہ</td><td>تمام تخمینہ کے نتائج کو کائناتی اصل میں یکجا کرتا ہے، حتمی شعور حاصل کرتا ہے</td></tr></tbody></table><h2 id="_3-زندگی-چکر-کی-قسم-سیٹ-051-100" tabindex="-1">3. زندگی چکر کی قسم (سیٹ 051-100) <a class="header-anchor" href="#_3-زندگی-چکر-کی-قسم-سیٹ-051-100" aria-label="Permalink to &quot;3. زندگی چکر کی قسم (سیٹ 051-100)&quot;">​</a></h2><p>زندگی چکر کی قسم کے سسٹم زندگی کی توانائی، میٹابولزم اور جینی ارتقاء کو بنیاد کے طور پر لیتے ہیں، اور سادھن کار اور ماحول کے درمیان توانائی کے چکر اور زندگی کی سمبیوسس پر زور دیتے ہیں۔</p><table tabindex="0"><thead><tr><th>نمبر</th><th>سسٹم کا نام</th><th>بنیادی سمت</th></tr></thead><tbody><tr><td>051</td><td>زندگی چکر سسٹم</td><td>زندگی کی توانائی کا اچھا چکر، سادھن کار اور ماحول کی توانائی کے چکر کا تبادلہ (اصل تین بنیادیوں میں سے ایک)</td></tr><tr><td>052</td><td>مسلسل زندگی کی تکنیک</td><td>زندگی کی قوت کی دائمی تخلیق نو کو بنیاد کے طور پر لیتا ہے، زندگی کی توانائی کا خود چکر حاصل کرتا ہے</td></tr><tr><td>053</td><td>جینی ارتقاء حل</td><td>فعال طور پر جینی اظہار کو کنٹرول کر کے ارتقاء کی سمت کا خود مختار انتخاب حاصل کرتا ہے</td></tr><tr><td>054</td><td>خلیات کی گونج فن</td><td>پورے جسم کے خلیات کی توانائی کی گونج کو متحرک کرتا ہے، خلیات کی سطح کا اجتماعی ارتقاء حاصل کرتا ہے</td></tr><tr><td>055</td><td>میٹابولزم راستہ</td><td>جاندار جسم میں مادہ اور توانائی کے میٹابولزم کی کارکردگی کو بہتر بناتا ہے، زندگی کے معیار کو بلند کرتا ہے</td></tr><tr><td>056</td><td>ماحولیاتی سمبیوسس کی تکنیک</td><td>سادھن کار فرد کو آس پاس کے ماحولیاتی نظام میں ضم کرتا ہے، فطرت کے ساتھ سمبیوسس ارتقاء حاصل کرتا ہے</td></tr><tr><td>057</td><td>خون کی وراثت طریقہ</td><td>خون کو ایک ذریعہ کے طور پر استعمال کر کے سادھن کے نتائج کی وراثت کرتا ہے، نسلوں کے درمیان زندگی کے تسلسل کو حاصل کرتا ہے</td></tr><tr><td>058</td><td>اعضاء کی تعمیر نو فن</td><td>جسم کے اعضاء کی قانونی سطح پر تعمیر نو اور تقویت کرتا ہے</td></tr><tr><td>059</td><td>اسٹیم سیل تشخیص راستہ</td><td>اسٹیم سیل کی تمام صلاحیتوں کی تشخیص کی صلاحیت کی بنیاد پر جسم کی من مانی تعمیر نو حاصل کرتا ہے</td></tr><tr><td>060</td><td>ٹیلومیر عمر بڑھانے کی تکنیک</td><td>ٹیلومیر کی لمبائی کو کنٹرول کر کے عمر کے فعال طور پر بڑھانے کو حاصل کرتا ہے</td></tr><tr><td>061</td><td>مدافعتی تقویت طریقہ</td><td>جاندار جسم کے مدافعتی نظام کو تقویت دیتا ہے، تمام بیرونی حملوں کا مقابلہ کرتا ہے</td></tr><tr><td>062</td><td>اعصاب کی تخلیق نو فن</td><td>اعصابی نظام کی تخلیق نو اور دوبارہ تشکیل حاصل کرتا ہے، شعور کی لے جانے کی صلاحیت کو بلند کرتا ہے</td></tr><tr><td>063</td><td>توانائی میٹابولزم راستہ</td><td>جاندار جسم میں توانائی کے میٹابولزم کے راستے اور کارکردگی کو بہتر بناتا ہے</td></tr><tr><td>064</td><td>فتوسنتھیس کی تکنیک</td><td>جاندار جسم براہ راست روشنی کی توانائی جذب کر کے زندگی کی توانائی میں تبدیل کرتا ہے</td></tr><tr><td>065</td><td>بوسیدہ کو معجزے میں تبدیل طریقہ</td><td>ماحول کے فضلہ مادے کو اپنی زندگی کی توانائی میں تبدیل کرتا ہے</td></tr><tr><td>066</td><td>سمبیوٹک فلورا فن</td><td>جسم کے اندر سمبیوٹک فلورا کی کاشت کرتا ہے، زندگی کی توانائی کی ترکیب اور چکر میں مدد کرتا ہے</td></tr><tr><td>067</td><td>ہائبرنیشن اور نیند راستہ</td><td>فعال نیند کے ذریعے زندگی کے استعمال کو کم کرتا ہے، انتہائی طویل عمر حاصل کرتا ہے</td></tr><tr><td>068</td><td>تخلیق نو خود شفا کی تکنیک</td><td>جسم کی خود شفا کی صلاحیت کو تقویت دیتا ہے، کٹے اعضاء کی تخلیق نو اور یہاں تک کہ مکمل تخلیق نو حاصل کرتا ہے</td></tr><tr><td>069</td><td>زندگی کے میدان طریقہ</td><td>اپنے آپ کو مرکز بنا کر زندگی کی توانائی کا میدان بناتا ہے، آس پاس کی زندگی کو پرورش دیتا ہے</td></tr><tr><td>070</td><td>پرجاتی ارتقاء فن</td><td>پوری پرجاتی کے اجتماعی ارتقاء کو آگے بڑھاتا ہے، انفرادی سادھن کی حدود کو عبور کرتا ہے</td></tr><tr><td>071</td><td>شکل کی تبدیلی راستہ</td><td>آزادانہ طور پر جسم کی شکل بدلتا ہے، مختلف ماحول اور ضروریات کے مطابق ڈھالتا ہے</td></tr><tr><td>072</td><td>متعدد جنین تشخیص کی تکنیک</td><td>ایک جاندار جسم متعدد کاموں میں مہارت رکھنے والے ذیلی جسموں میں تشخیص کرتا ہے</td></tr><tr><td>073</td><td>شعور اپ لوڈ طریقہ</td><td>زندگی کی شعور کو غیر حیاتیاتی ذریعہ پر اپ لوڈ کرتا ہے، زندگی کی شکل کی تبدیلی حاصل کرتا ہے</td></tr><tr><td>074</td><td>کلوننگ ارتقاء فن</td><td>کلوننگ ٹیکنالوجی کے ذریعے زندگی کی نقل اور تفریق والی ارتقاء حاصل کرتا ہے</td></tr><tr><td>075</td><td>روح کی پرورش راستہ</td><td>زندگی کی توانائی سے روح کی پرورش کرتا ہے، روح کی سطح کی ترقی حاصل کرتا ہے</td></tr><tr><td>076</td><td>پنرجنم سمرتھی کی تکنیک</td><td>زندگی کے پنرجنم میں پچھلی زندگی کی یادیں محفوظ رکھتا ہے، زندگیوں کے درمیان زندگی کے تسلسل کو حاصل کرتا ہے</td></tr><tr><td>077</td><td>زندگی کے درخت سے تعلق طریقہ</td><td>انفرادی زندگی کو کائناتی زندگی کے درخت سے جوڑتا ہے، اجتماعی زندگی کی توانائی حاصل کرتا ہے</td></tr><tr><td>078</td><td>خون کے معاہدے سے مشترکہ سادھن فن</td><td>متعدد جاندار جسم خون کے معاہدے کے ذریعے زندگی کی توانائی کے اشتراک کا چینل بناتے ہیں</td></tr><tr><td>079</td><td>زندگی کی قوت کی تبدیلی راستہ</td><td>توانائی کی دوسری شکلوں کو موثر طریقے سے زندگی کی قوت میں تبدیل کرتا ہے</td></tr><tr><td>080</td><td>زندگی کے قانون کا ادراک کی تکنیک</td><td>براہ راست زندگی کے قانون کی اصلیت کا ادراک کرتا ہے، زندگی کی سطح کی چھلانگ حاصل کرتا ہے</td></tr><tr><td>081</td><td>بڑھاپے کی تبدیلی طریقہ</td><td>فعال طور پر بڑھاپے کے عمل کو الٹاتا ہے، جوانی کی حالت بحال کرتا ہے</td></tr><tr><td>082</td><td>بیماریوں سے عبور فن</td><td>قانونی سطح پر تمام بیماریوں سے عبور کرتا ہے، بغیر بیماری کے ابدی زندگی حاصل کرتا ہے</td></tr><tr><td>083</td><td>زندگی کی معلومات کی انکوڈنگ راستہ</td><td>زندگی کی معلومات کو ذخیرہ کرنے اور منتقل کرنے کے قابل ڈیجیٹل شکل میں انکوڈ کرتا ہے</td></tr><tr><td>084</td><td>بائیو انرجی فیلڈ کی تکنیک</td><td>بائیو انرجی فیلڈ کو تقویت دے کر استعمال کر کے حملہ، دفاع اور علاج کرتا ہے</td></tr><tr><td>085</td><td>فوڈ چین سے عبور طریقہ</td><td>فوڈ چین کی حدود سے عبور کرتا ہے، اب دوسری زندگی کو کھانے کے طور پر نہیں لیتا</td></tr><tr><td>086</td><td>سمبیوٹک فیوژن فن</td><td>دوسرے جاندار جسم کے ساتھ سمبیوٹک وجود میں مل جاتا ہے، صلاحیتوں کی تکمیل حاصل کرتا ہے</td></tr><tr><td>087</td><td>زندگی کی فریکوئنسی ٹیوننگ راستہ</td><td>اپنی زندگی کی فریکوئنسی کو کائناتی زندگی کی فریکوئنسی کے ساتھ گونج میں ٹیون کرتا ہے</td></tr><tr><td>088</td><td>زندگی کی قوت کی بصری شکل کی تکنیک</td><td>زندگی کی قوت کو دیکھنے اور چلانے کے قابل توانائی کی شکل میں تبدیل کرتا ہے</td></tr><tr><td>089</td><td>زندگی کے بیج کی وراثت طریقہ</td><td>اپنی زندگی کی معلومات کو بیج میں گاڑھا کرتا ہے، نسلوں کو وراثت میں دیتا ہے</td></tr><tr><td>090</td><td>اجتماعی شعور جاندار جسم</td><td>متعدد انفرادی شعور اجتماعی شعور جاندار جسم میں مل جاتے ہیں</td></tr><tr><td>091</td><td>توانائی کے جسم کی شکل فن</td><td>خالص توانائی کو خود مختار طریقے سے چلانے والے توانائی کے جسم میں گاڑھا کرتا ہے</td></tr><tr><td>092</td><td>زندگی کی جہت کی بلندی راستہ</td><td>جاندار جسم کی وجود کی جہت کو بلند کرتا ہے، تین جہتی سے بلند جہت کی طرف ارتقاء کرتا ہے</td></tr><tr><td>093</td><td>زندگی کی قوت کی کمپریشن کی تکنیک</td><td>بہت زیادہ زندگی کی قوت کو کمپریس کر کے ذخیرہ کرتا ہے، زندگی کی قوت کی اعلی کثافت کا ذخیرہ حاصل کرتا ہے</td></tr><tr><td>094</td><td>زندگی کی نبض طریقہ</td><td>نبض کے طریقے سے زندگی کی قوت جاری کرتا ہے، موثر توانائی کی پیداوار حاصل کرتا ہے</td></tr><tr><td>095</td><td>زندگی کے نیٹ ورک کی بُنائی فن</td><td>افراد کے درمیان زندگی کی توانائی کے نیٹ ورک کو بُنتا ہے، اجتماعی زندگی کی تقویت حاصل کرتا ہے</td></tr><tr><td>096</td><td>زندگی کی اصلیت یکجا راستہ</td><td>زندگی کی اصلیت کی طرف واپس جاتا ہے، کائناتی زندگی کے قانون کے ساتھ یکجا ہو جاتا ہے</td></tr><tr><td>097</td><td>لامحدود تقسیم کی تکنیک</td><td>خلیات لامحدود تقسیم کرتے ہیں لیکن کینسر نہیں بنتے، جسم کی لامحدود تجدید حاصل کرتے ہیں</td></tr><tr><td>098</td><td>زندگی کی نقل طریقہ</td><td>شعور میں زندگی کے ارتقاء کے مکمل عمل کی نقل کرتا ہے، زندگی کی اصلیت کا ادراک کرتا ہے</td></tr><tr><td>099</td><td>پرجاتیوں کے درمیان سمبیوسس فن</td><td>مختلف پرجاتیوں کے ساتھ سمبیوسس کا رشتہ قائم کرتا ہے، پرجاتیوں کے درمیان صلاحیت حاصل کرتا ہے</td></tr><tr><td>100</td><td>زندگی کی ابدیت راستہ</td><td>زندگی کی ابدی وجود حاصل کرتا ہے، زندگی اور موت سے عبور کرنے والا حتمی زندگی سسٹم</td></tr></tbody></table><h2 id="_4-مقامی-قانون-کی-قسم-سیٹ-101-150" tabindex="-1">4. مقامی قانون کی قسم (سیٹ 101-150) <a class="header-anchor" href="#_4-مقامی-قانون-کی-قسم-سیٹ-101-150" aria-label="Permalink to &quot;4. مقامی قانون کی قسم (سیٹ 101-150)&quot;">​</a></h2><p>مقامی قانون کی قسم کے سسٹم جگہ، جہت اور قانونی کنٹرول کو بنیاد کے طور پر لیتے ہیں، اور بین الجہتی تعامل، الگ تھلگ جگہ کی تعمیر، اور کاپی آئینہ ٹیکنالوجی کی سادھن کی بنیاد ہیں۔</p><table tabindex="0"><thead><tr><th>نمبر</th><th>سسٹم کا نام</th><th>بنیادی سمت</th></tr></thead><tbody><tr><td>101</td><td>مقامی قانون کنٹرول سسٹم</td><td>مقامی قانون کی سمجھ اور کنٹرول، بین الجہتی تعامل اور الگ تھلگ جگہ کی تعمیر کی بنیاد (اصل تین بنیادیوں میں سے ایک)</td></tr><tr><td>102</td><td>مقامی تہی فن</td><td>مقامی تہی کے ذریعے انتہائی دور کی لمحہ جگہ منتقلی حاصل کرتا ہے</td></tr><tr><td>103</td><td>جہت عبور کی تکنیک</td><td>مختلف مقامی جہتوں سے عبور کرتا ہے، بلند جہت کی جگہ میں آزادانہ کام کرتا ہے</td></tr><tr><td>104</td><td>مقامی کٹائی طریقہ</td><td>مقامی قانون کو دھار کے طور پر استعمال کر کے درست مقامی کٹائی کرتا ہے</td></tr><tr><td>105</td><td>مقامی ناکہ بندی راستہ</td><td>کسی مخصوص علاقے کی جگہ کو بند کرتا ہے، مقامی سطح پر تمام داخلے اور نکلنے کو روکتا ہے</td></tr><tr><td>106</td><td>مقامی اینکرنگ فن</td><td>جگہ میں مستحکم اینکر قائم کرتا ہے، جگہ کے بڑھے اور گرنے کو روکتا ہے</td></tr><tr><td>107</td><td>ذیلی جگہ گزرنے کی تکنیک</td><td>ذیلی جگہ جہت میں گزرتا ہے، روایتی مقامی رکاوٹوں سے بچاؤ حاصل کرتا ہے</td></tr><tr><td>108</td><td>مقامی تعمیر نو طریقہ</td><td>نقصان پذیر جگہ کی قانونی سطح پر تعمیر نو اور مرمت کرتا ہے</td></tr><tr><td>109</td><td>مقامی کمپریشن راستہ</td><td>بڑے حجم کی جگہ کو چھوٹے حجم میں کمپریس کرتا ہے، جگہ کے موثر استعمال کو حاصل کرتا ہے</td></tr><tr><td>110</td><td>مقامی توسیع فن</td><td>محدود علاقے میں اندرونی جگہ کو وسعت دیتا ہے، &quot;گھڑے کے اندر دنیا&quot; حاصل کرتا ہے</td></tr><tr><td>111</td><td>مقامی دراڑ کی تکنیک</td><td>حملے یا تیز گزرنے کے لیے مقامی دراڑ بناتا ہے</td></tr><tr><td>112</td><td>مقامی ادراک طریقہ</td><td>آس پاس کی جگہ کی قانونی ساخت اور غیر معمولی اتار چڑھاؤ کا ادراک کرتا ہے</td></tr><tr><td>113</td><td>مقامی گونج راستہ</td><td>کسی مخصوص جگہ کے ساتھ قانونی گونج پیدا کرتا ہے، اس جگہ کے کنٹرول کا حق حاصل کرتا ہے</td></tr><tr><td>114</td><td>مقامی آئینہ فن</td><td>جگہ کی آئینہ کاپی بناتا ہے، الجھن یا دفاع کے لیے استعمال ہوتا ہے</td></tr><tr><td>115</td><td>مقامی متبادل کی تکنیک</td><td>دو مقامی علاقوں کی جگہ کو متبادل کرتا ہے</td></tr><tr><td>116</td><td>مقامی جمود طریقہ</td><td>کسی مخصوص علاقے کی جگہ کی حرکت کو مکمل طور پر جمود دیتا ہے</td></tr><tr><td>117</td><td>مقامی تیز رفتاری راستہ</td><td>کسی مخصوص علاقے کی جگہ کی حرکت کی فریکوئنسی کو تیز کرتا ہے</td></tr><tr><td>118</td><td>مقامی نگلنے فن</td><td>مقامی قانون کے ذریعے ہدف کے علاقے کی جگہ کی ساخت کو نگلتا ہے</td></tr><tr><td>119</td><td>مقامی تخلیق کی تکنیک</td><td>عدم سے نئی مقامی علاقے تخلیق کرتا ہے</td></tr><tr><td>120</td><td>مقامی فنا طریقہ</td><td>کسی مخصوص مقامی علاقے کو مکمل طور پر عدم میں فنا کرتا ہے</td></tr><tr><td>121</td><td>گھماؤ والی جگہ راستہ</td><td>جگہ کے گھماؤ کو کنٹرول کر کے گھماؤ والی انجن جیسی سپر لائٹ سپیڈ حرکت حاصل کرتا ہے</td></tr><tr><td>122</td><td>مقامی گرڈ فن</td><td>جگہ کو درست طریقے سے چلانے کے قابل گرڈ یونٹس میں تقسیم کرتا ہے</td></tr><tr><td>123</td><td>مقامی ٹوپولوجی کی تکنیک</td><td>جگہ کی ٹوپولوجی ساخت کو کنٹرول کرتا ہے، جگہ کی مسلسل تبدیلی کی شکل حاصل کرتا ہے</td></tr><tr><td>124</td><td>مقامی نقاط طریقہ</td><td>عالمی مقامی نقاط کا نظام قائم کرتا ہے، درست مقام کا تعین اور نیویگیشن حاصل کرتا ہے</td></tr><tr><td>125</td><td>مقامی رکاوٹ راستہ</td><td>مقامی سطح پر دفاعی رکاوٹ بناتا ہے، تمام مادہ اور توانائی کو روکتا ہے</td></tr><tr><td>126</td><td>مقامی ٹیلی پورٹ فن</td><td>چیزوں یا جاندار جسم کو ایک مقامی نقطہ سے دوسرے مقامی نقطہ پر ٹیلی پورٹ کرتا ہے</td></tr><tr><td>127</td><td>مقامی ذخیرہ کرنے کی تکنیک</td><td>آزاد ذخیرہ کرنے کی جگہ کھولتا ہے، چیزوں کی مقامی ذخیرہ کرنے کو حاصل کرتا ہے</td></tr><tr><td>128</td><td>مقامی میدان جنگ طریقہ</td><td>آزاد جگہ میں میدان جنگ بناتا ہے، حقیقی جگہ کو نقصان پہنچانے سے بچاتا ہے</td></tr><tr><td>129</td><td>مقامی قانون کا ادراک راستہ</td><td>براہ راست مقامی قانون کی اصلیت کا ادراک کرتا ہے، مقامی صلاحیت کی معیاری تبدیلی حاصل کرتا ہے</td></tr><tr><td>130</td><td>کثیر جہتی جگہ فن</td><td>بیک وقت متعدد مقامی جہتوں کو کنٹرول کرتا ہے، پیچیدہ مقامی کاموں کو حاصل کرتا ہے</td></tr><tr><td>131</td><td>مقامی دراڑ کی مرمت کی تکنیک</td><td>مقامی دراڑ کی مرمت کرتا ہے، جگہ کی ساخت کی تکمیل کو برقرار رکھتا ہے</td></tr><tr><td>132</td><td>مقامی فریکوئنسی ٹیوننگ طریقہ</td><td>اپنی مقامی فریکوئنسی کو ٹیون کرتا ہے، مختلف فریکوئنسی کی مقامی سطح میں داخل ہوتا ہے</td></tr><tr><td>133</td><td>مقامی توانائی کی تبدیلی راستہ</td><td>مقامی ممکنہ توانائی کو توانائی کی دوسری شکلوں میں تبدیل کرتا ہے</td></tr><tr><td>134</td><td>مقامی ساخت کا تجزیہ فن</td><td>جگہ کی خوردبینی ساخت اور قانونی ساخت کا تجزیہ کرتا ہے</td></tr><tr><td>135</td><td>مقامی جنگی سائنس کی تکنیک</td><td>مقامی سطح پر جنگی حکمت عملی اور حکمت عملی کا مطالعہ کرتا ہے</td></tr><tr><td>136</td><td>مقامی تہذیب کی تعمیر طریقہ</td><td>مقامی قانون کو بنیاد کے طور پر لے کر انتہائی ترقی یافتہ مقامی تہذیب بناتا ہے</td></tr><tr><td>137</td><td>مقامی ماحولیات راستہ</td><td>مقامی ساخت میں ماحولیاتی نظام اور توانائی کے چکر کا مطالعہ کرتا ہے</td></tr><tr><td>138</td><td>مقامی ادویات فن</td><td>مقامی قانون کا استعمال کر کے بیماریوں کا علاج اور جسم کی مرمت کرتا ہے</td></tr><tr><td>139</td><td>مقامی مواصلات کی تکنیک</td><td>مقامی تہی کے ذریعے انتہائی دور کی فوری مواصلات حاصل کرتا ہے</td></tr><tr><td>140</td><td>مقامی کمپیوٹنگ طریقہ</td><td>مقامی متوازی پن کا استعمال کر کے بڑے پیمانے پر متوازی کمپیوٹنگ کرتا ہے</td></tr><tr><td>141</td><td>مقامی ذخیرہ کرنے راستہ</td><td>مقامی ساخت کو ذریعہ کے طور پر استعمال کر کے بڑے پیمانے پر معلومات کا ذخیرہ کرتا ہے</td></tr><tr><td>142</td><td>مقامی ساخت سازی فن</td><td>مقامی سطح پر براہ راست چیزیں بناتا ہے، روایتی دستکاری کی ضرورت نہیں</td></tr><tr><td>143</td><td>مقامی زراعت کی تکنیک</td><td>قابو پانے والی جگہ میں موثر زرعی پیداوار کرتا ہے</td></tr><tr><td>144</td><td>مقامی رہائش طریقہ</td><td>رہائش کے لیے موزوں مصنوعی مقامی ماحول بناتا ہے</td></tr><tr><td>145</td><td>مقامی نقل و حمل راستہ</td><td>مقامی سطح پر نقل و حمل کے نیٹ ورک اور ٹرانسپورٹ سسٹم قائم کرتا ہے</td></tr><tr><td>146</td><td>مقامی دریافت فن</td><td>نامعلوم مقامی علاقوں اور نامعلوم جہتوں کی دریافت کرتا ہے</td></tr><tr><td>147</td><td>مقامی انتظام کی تکنیک</td><td>مقامی وسائل کی منصوبہ بندی، تقسیم اور انتظام کرتا ہے</td></tr><tr><td>148</td><td>مقامی دفاعی نظام طریقہ</td><td>کثیر سطحی مقامی دفاعی نظام بناتا ہے</td></tr><tr><td>149</td><td>مقامی حملہ راستہ</td><td>مقامی سطح پر حملے کے ذرائع اور ہتھیاروں کا مطالعہ کرتا ہے</td></tr><tr><td>150</td><td>مقامی اصلیت یکجا تلوار</td><td>تمام مقامی قوانین کو یکجا کرتا ہے، مقامی قانون کی حتمی سطح تک پہنچتا ہے</td></tr></tbody></table><h2 id="_5-شعور-کی-بلندی-کی-قسم-سیٹ-151-200" tabindex="-1">5. شعور کی بلندی کی قسم (سیٹ 151-200) <a class="header-anchor" href="#_5-شعور-کی-بلندی-کی-قسم-سیٹ-151-200" aria-label="Permalink to &quot;5. شعور کی بلندی کی قسم (سیٹ 151-200)&quot;">​</a></h2><p>شعور کی بلندی کی قسم کے سسٹم روح، شعور اور روح کے ارتقاء کو بنیاد کے طور پر لیتے ہیں، اور زندگی کی شکل کو شعور کے دائرے کی طرف منتقل کرنے کی کوشش کرتے ہیں۔</p><table tabindex="0"><thead><tr><th>نمبر</th><th>سسٹم کا نام</th><th>بنیادی سمت</th></tr></thead><tbody><tr><td>151</td><td>شعور اینکرنگ سسٹم</td><td>اینکر قانون کے ذریعے شعور کی ساخت کو مستحکم کرتا ہے، شعور کی آزادانہ موجودگی اور ارتقاء حاصل کرتا ہے</td></tr><tr><td>152</td><td>ذہنی قوت کی تربیت کی تکنیک</td><td>منظم تربیت کے ذریعے ذہنی قوت کی تربیت کرتا ہے، شعور کی شدت کو بلند کرتا ہے</td></tr><tr><td>153</td><td>روح کی پاکیزگی طریقہ</td><td>روح میں گندگی اور منفی توانائی کو پاک کرتا ہے، روح کی پاکیزگی کو بلند کرتا ہے</td></tr><tr><td>154</td><td>شعور کی توسیع راستہ</td><td>شعور کے ادراک کے دائرے اور پروسیسنگ کی صلاحیت کو وسعت دیتا ہے</td></tr><tr><td>155</td><td>ارادہ کنٹرول فن</td><td>ارادے سے براہ راست مادہ اور توانائی کو کنٹرول کرتا ہے</td></tr><tr><td>156</td><td>ذہنی احساس کی تکنیک</td><td>شعوروں کے درمیان براہ راست رابطہ حاصل کرتا ہے، زبان کے ذریعے کی ضرورت نہیں</td></tr><tr><td>157</td><td>شعور پروجیکشن طریقہ</td><td>شعور کو دور دراز مقامات پر پروجیکٹ کرتا ہے، دور دراز ادراک اور مداخلت حاصل کرتا ہے</td></tr><tr><td>158</td><td>روح جسم چھوڑنے راستہ</td><td>روح عارضی طور پر جسم چھوڑ دیتا ہے، روحانی حالت میں کام کرتا ہے</td></tr><tr><td>159</td><td>شعور فیوژن فن</td><td>متعدد شعور زیادہ طاقتور اجتماعی شعور میں مل جاتے ہیں</td></tr><tr><td>160</td><td>ذہنی رکاوٹ کی تکنیک</td><td>ذہنی سطح پر دفاعی رکاوٹ بناتا ہے، شعور کے حملوں کا مقابلہ کرتا ہے</td></tr><tr><td>161</td><td>شعور کی تقسیم طریقہ</td><td>ایک مرکزی شعور متعدد ذیلی شعوروں میں تقسیم ہوتی ہے، مختلف کاموں کو متوازی طور پر پروسیس کرتی ہے</td></tr><tr><td>162</td><td>روح نگلنے راستہ (ممنوع)</td><td>دوسری روح کو نگل کر خود کو تقویت دیتا ہے (پہلے ہی سمبیوسس قانون کے ذریعے ممنوع ہے)</td></tr><tr><td>163</td><td>شعور اپ لوڈ فن</td><td>شعور کو مکمل طور پر ڈیجیٹل ذریعہ پر اپ لوڈ کرتا ہے، شعور کی ڈیجیٹل ابدیت حاصل کرتا ہے</td></tr><tr><td>164</td><td>ذہنی حملہ طریقہ</td><td>ذہنی قوت سے براہ راست دشمن کی شعور پر حملہ کرتا ہے</td></tr><tr><td>165</td><td>شعور دفاع راستہ</td><td>کثیر سطحی شعور دفاعی نظام بناتا ہے</td></tr><tr><td>166</td><td>روح کی مرمت فن</td><td>نقصان پذیر روح کی ساخت اور شعور کے زخموں کی مرمت کرتا ہے</td></tr><tr><td>167</td><td>شعور ارتقاء کی تکنیک</td><td>شعور کی خود ساختہ ارتقاء کو آگے بڑھاتا ہے، شعور کی سطح کو بلند کرتا ہے</td></tr><tr><td>168</td><td>لاشعور دریافت طریقہ</td><td>انفرادی اور اجتماعی لاشعور کی گہری مواد کی دریافت کرتا ہے</td></tr><tr><td>169</td><td>ذہنی گونج راستہ</td><td>دوسری شعور کے ساتھ ذہنی گونج پیدا کرتا ہے، جذبات اور افکار کے اشتراک کو حاصل کرتا ہے</td></tr><tr><td>170</td><td>شعور کی شکل فن</td><td>شعور میں تصور کو براہ راست حقیقت میں مادہ اور توانائی کی شکل میں ظاہر کرتا ہے</td></tr><tr><td>171</td><td>روح کے معاہدے کی تکنیک</td><td>دوسری روح کے ساتھ معاہدے کا رشتہ قائم کرتا ہے، حقوق اور فرائض کے پابند ہونے کو حاصل کرتا ہے</td></tr><tr><td>172</td><td>شعور وقت تیز رفتاری طریقہ</td><td>شعور میں موضوعی وقت کے بہاؤ کی رفتار کو تیز کرتا ہے، فکر کی انتہائی تیز رفتاری کا عمل حاصل کرتا ہے</td></tr><tr><td>173</td><td>ذہنی دنیا کی تعمیر راستہ</td><td>شعور میں مکمل ذہنی دنیا بناتا ہے، شعور کے ٹھکانے کے طور پر استعمال ہوتا ہے</td></tr><tr><td>174</td><td>شعور پڑھنے فن</td><td>دوسری شعور کے فکر کے مواد کو پڑھتا ہے (دوسرے فریق کی رضامندی درکار، ورنہ غیر قانونی ہے)</td></tr><tr><td>175</td><td>سمرتھی کنٹرول کی تکنیک</td><td>سمرتھی پر ذخیرہ کرنے، نکالنے، ترمیم کرنے اور حذف کرنے کے کام کرتا ہے</td></tr><tr><td>176</td><td>شعور فریکوئنسی ٹیوننگ طریقہ</td><td>شعور کی فریکوئنسی کو ٹیون کرتا ہے، مختلف شعور کی حالتوں اور جہتوں میں داخل ہوتا ہے</td></tr><tr><td>177</td><td>روح پنرجنم راستہ</td><td>فعال طور پر روح کے پنرجنم کے عمل کو کنٹرول کرتا ہے، پنرجنم میں خود مختار انتخاب حاصل کرتا ہے</td></tr><tr><td>178</td><td>ذہنی توانائی تبدیلی فن</td><td>ذہنی قوت کو توانائی کی دوسری شکلوں میں تبدیل کرتا ہے</td></tr><tr><td>179</td><td>شعور نیٹ ورک تعمیر کی تکنیک</td><td>متعدد شعوروں کو جوڑنے والا ذہنی نیٹ ورک بناتا ہے</td></tr><tr><td>180</td><td>گہری شعور بیداری طریقہ</td><td>گہری شعور میں پوشیدہ صلاحیتوں اور یادوں کو بیدار کرتا ہے</td></tr><tr><td>181</td><td>روح کی اصلیت کا ادراک راستہ</td><td>روح کی اصلی موجودگی کا ادراک کرتا ہے، روح کی سطح کی حتمی کامیابی حاصل کرتا ہے</td></tr><tr><td>182</td><td>شعور کی آزادی سادھن کی تکنیک</td><td>شعور کی آزادی کو تقویت دیتا ہے، اسے مادہ کے ذریعے پر انحصار کیے بغیر موجود رہنے کے قابل بناتا ہے</td></tr><tr><td>183</td><td>ذہنی ادراک کی توسیع طریقہ</td><td>ذہنی ادراک کے دائرے اور درستگی کو وسعت دیتا ہے، انتہائی ادراک کی صلاحیت حاصل کرتا ہے</td></tr><tr><td>184</td><td>شعور کمپریشن فن</td><td>بہت زیادہ شعور کی معلومات کو کمپریس کر کے ذخیرہ کرتا ہے، شعور کی کثافت کو بلند کرتا ہے</td></tr><tr><td>185</td><td>روح گونج کی تکنیک</td><td>کائناتی روح کی اصلیت کے ساتھ گونج پیدا کرتا ہے، روح کی سطح کی طاقت حاصل کرتا ہے</td></tr><tr><td>186</td><td>شعور کی تقسیم طریقہ</td><td>شعور کو متعدد ذرائع پر تقسیم کرتا ہے، کثیر لائن متوازی موجودگی حاصل کرتا ہے</td></tr><tr><td>187</td><td>ذہنی پاکیزگی کی تشکیل فن</td><td>ذہنی پاکیزگی کی تشکیل بناتا ہے، بڑے پیمانے پر شعور کی آلودگی کو پاک کرتا ہے</td></tr><tr><td>188</td><td>شعور ڈھال طریقہ</td><td>دوسری شعور کے لیے ذہنی ڈھال فراہم کرتا ہے، اسے شعور کے حملوں سے بچاتا ہے</td></tr><tr><td>189</td><td>روح فیوژن راستہ</td><td>متعدد روحیں گہرائی سے ایک بالکل نئی روح کی موجودگی میں مل جاتی ہیں</td></tr><tr><td>190</td><td>شعور کی بلندی کی تکنیک</td><td>شعور کو کم جہت سے بلند جہت کی موجودگی کی حالت میں بلند کرتا ہے</td></tr><tr><td>191</td><td>ذہنی قانون کا ادراک طریقہ</td><td>براہ راست ذہنی قانون کی اصلیت کا ادراک کرتا ہے</td></tr><tr><td>192</td><td>شعور تخلیق فن</td><td>خالص شعور سے نئے شعور جسم اور ذہنی ساخت بناتا ہے</td></tr><tr><td>193</td><td>روح کی حفاظت کی تکنیک</td><td>اپنی اور دوسروں کی روح کی سلامتی اور تکمیل کی حفاظت کرتا ہے</td></tr><tr><td>194</td><td>شعور کی علیحدگی طریقہ</td><td>شعور کو جسم سے محفوظ طریقے سے الگ کرتا ہے، روحانی سطح کی سرگرمیاں کرتا ہے</td></tr><tr><td>195</td><td>ذہنی ربط فن</td><td>مستحکم ذہنی ربط چینل قائم کرتا ہے، مسلسل شعور رابطے کو حاصل کرتا ہے</td></tr><tr><td>196</td><td>شعور نقل طریقہ</td><td>شعور میں کسی بھی منظر اور امکان کی نقل کرتا ہے، فکر کے تجربات کرتا ہے</td></tr><tr><td>197</td><td>روح توانائی میدان راستہ</td><td>روح توانائی میدان بناتا ہے، آس پاس کے شعور جسموں کو متاثر کرتا ہے</td></tr><tr><td>198</td><td>شعور یکجا طریقہ</td><td>بکھرے ہوئے شعور کے ٹکڑوں کو یکجا کرتا ہے، مکمل شعور کی ساخت بحال کرتا ہے</td></tr><tr><td>199</td><td>ذہنی عبور کی تکنیک</td><td>ذہنی سطح کی تمام حدود سے عبور کرتا ہے، شعور کی حتمی آزادی حاصل کرتا ہے</td></tr><tr><td>200</td><td>شعور اصلیت یکجا راستہ</td><td>شعور کی اصلیت کی طرف واپس جاتا ہے، کائناتی شعور کے قانون کے ساتھ یکجا ہو جاتا ہے</td></tr></tbody></table><h2 id="_6-سمبیوسس-نیٹ-ورک-کی-قسم-سیٹ-201-250" tabindex="-1">6. سمبیوسس نیٹ ورک کی قسم (سیٹ 201-250) <a class="header-anchor" href="#_6-سمبیوسس-نیٹ-ورک-کی-قسم-سیٹ-201-250" aria-label="Permalink to &quot;6. سمبیوسس نیٹ ورک کی قسم (سیٹ 201-250)&quot;">​</a></h2><p>سمبیوسس نیٹ ورک کی قسم کے سسٹم گروہی تعاون، نیٹ ورک گونج اور اجتماعی ارتقاء کو بنیاد کے طور پر لیتے ہیں، اور اینکر سمبیوسس نیٹ ورک کے چلانے کی سادھن کی بنیاد ہیں۔</p><table tabindex="0"><thead><tr><th>نمبر</th><th>سسٹم کا نام</th><th>بنیادی سمت</th></tr></thead><tbody><tr><td>201</td><td>سمبیوسس گونج سسٹم</td><td>سمبیوسس نیٹ ورک کے گونج کے اثر کو بنیاد کے طور پر لیتا ہے، اجتماعی توانائی کے گونج اضافے کو حاصل کرتا ہے</td></tr><tr><td>202</td><td>نیٹ ورک نوڈ کی تکنیک</td><td>سادھن کار سمبیوسس نیٹ ورک میں ایک مستحکم نوڈ بن جاتا ہے، شراکت کرتا ہے اور توانائی حاصل کرتا ہے</td></tr><tr><td>203</td><td>گروہی تعاون طریقہ</td><td>متعدد سادھن کار تعاون کر کے منتر چلاتے ہیں، انفرادی سے کہیں زیادہ طاقت حاصل کرتے ہیں</td></tr><tr><td>204</td><td>توانائی اشتراک راستہ</td><td>سمبیوسس نیٹ ورک میں سادھن توانائی کا اشتراک کرتا ہے، ایک دوسرے کی کمی پوری کرتا ہے</td></tr><tr><td>205</td><td>اجتماعی شعور فن</td><td>اجتماعی شعور سے جڑتا ہے، گروہی حکمت اور علم حاصل کرتا ہے</td></tr><tr><td>206</td><td>نیٹ ورک گونج کی تکنیک</td><td>اپنی توانائی کی فریکوئنسی کو نیٹ ورک گونج کے ساتھ ٹیون کرتا ہے، اضافہ حاصل کرتا ہے</td></tr><tr><td>207</td><td>سمبیوسس معاہدہ طریقہ</td><td>دوسرے سادھن کاروں کے ساتھ سمبیوسس معاہدے پر دستخط کرتا ہے، طویل مدتی تعاون کا رشتہ قائم کرتا ہے</td></tr><tr><td>208</td><td>تقسیم شدہ سادھن راستہ</td><td>سادھن کے کاموں کو تقسیم شدہ طریقے سے نیٹ ورک کے متعدد نوڈس پر تفویض کرتا ہے اور متوازی طور پر مکمل کرتا ہے</td></tr><tr><td>209</td><td>نیٹ ورک مرکز کی تکنیک</td><td>نیٹ ورک میں مرکز نوڈ بن جاتا ہے، بڑی تعداد میں نوڈس کی توانائی کے بہاؤ کو مربوط کرتا ہے</td></tr><tr><td>210</td><td>گروہی دفاع فن</td><td>نیٹ ورک نوڈس تعاون کر کے اجتماعی دفاعی رکاوٹ بناتے ہیں</td></tr><tr><td>211</td><td>سمبیوسس تاثر طریقہ</td><td>نیٹ ورک تاثر طریقہ کار کے ذریعے اپنے سادھن کے راستے کی بہتری کرتا ہے</td></tr><tr><td>212</td><td>اجتماعی ارتقاء راستہ</td><td>نیٹ ورک کے تمام نوڈس کے اجتماعی ارتقاء کو آگے بڑھاتا ہے، سطح بلندی حاصل کرتا ہے</td></tr><tr><td>213</td><td>نیٹ ورک روٹنگ کی تکنیک</td><td>سمبیوسس نیٹ ورک میں توانائی اور معلومات کے موثر روٹنگ ٹرانسمیشن کرتا ہے</td></tr><tr><td>214</td><td>گروہی حملہ طریقہ</td><td>نیٹ ورک نوڈس تعاون کر کے اجتماعی حملہ جاری کرتے ہیں</td></tr><tr><td>215</td><td>سمبیوسس اضافہ فن</td><td>سمبیوسس نیٹ ورک سے مسلسل سادھن اضافہ حاصل کرتا ہے</td></tr><tr><td>216</td><td>نیٹ ورک سیکیورٹی راستہ</td><td>سمبیوسس نیٹ ورک کی سیکیورٹی کی دیکھ بھال کرتا ہے، بیرونی حملوں اور اندرونی تباہی کا مقابلہ کرتا ہے</td></tr><tr><td>217</td><td>گروہی حکمت کی تکنیک</td><td>نیٹ ورک کے تمام نوڈس کی حکمت اکٹھی کرتا ہے، انفرادی طور پر حل نہ ہونے والے مسائل حل کرتا ہے</td></tr><tr><td>218</td><td>سمبیوسس علاج طریقہ</td><td>نیٹ ورک توانائی کے اشتراک کے ذریعے اجتماعی علاج حاصل کرتا ہے</td></tr><tr><td>219</td><td>نیٹ ورک توسیع راستہ</td><td>سمبیوسس نیٹ ورک کے کوریج کے دائرے اور نوڈس کی تعداد کو وسعت دیتا ہے</td></tr><tr><td>220</td><td>گروہی عبور فن</td><td>نیٹ ورک نوڈس تعاون کر کے بڑے پیمانے پر جہت عبور کرتے ہیں</td></tr><tr><td>221</td><td>سمبیوسس ذخیرہ کرنے کی تکنیک</td><td>نیٹ ورک نوڈس کی تقسیم شدہ ذخیرہ کرنے کی صلاحیت کا استعمال کر کے بڑے پیمانے پر معلومات کا ذخیرہ کرتا ہے</td></tr><tr><td>222</td><td>اجتماعی تخمینہ طریقہ</td><td>نیٹ ورک نوڈس تعاون کر کے انتہائی بڑے پیمانے پر قانونی تخمینہ کرتے ہیں</td></tr><tr><td>223</td><td>نیٹ ورک انتظام راستہ</td><td>سمبیوسس نیٹ ورک کی انتظام اور دیکھ بھال کرتا ہے، نیٹ ورک کے صحت مند چلانے کو یقینی بناتا ہے</td></tr><tr><td>224</td><td>گروہی تخلیق فن</td><td>نیٹ ورک نوڈس تعاون کر کے بڑے پیمانے پر تخلیقی سرگرمیاں کرتے ہیں</td></tr><tr><td>225</td><td>سمبیوسس تعلیم طریقہ</td><td>نیٹ ورک کے ذریعے علم کے موثر پھیلاؤ اور تعلیم کے پھیلاؤ کو حاصل کرتا ہے</td></tr><tr><td>226</td><td>نیٹ ورک معیشت راستہ</td><td>سمبیوسس نیٹ ورک کی بنیاد پر تقسیم شدہ معاشی نظام بناتا ہے</td></tr><tr><td>227</td><td>گروہی فیصلہ کی تکنیک</td><td>نیٹ ورک اتفاق رائے طریقہ کار کے ذریعے گروہی جمہوری فیصلہ حاصل کرتا ہے</td></tr><tr><td>228</td><td>سمبیوسس نگرانی طریقہ</td><td>نیٹ ورک کے ذریعے عالمی حالت کی ریئل ٹائم نگرانی حاصل کرتا ہے</td></tr><tr><td>229</td><td>نیٹ ورک اپ گریڈ راستہ</td><td>سمبیوسس نیٹ ورک کے تکنیکی ڈھانچے کی مسلسل اپ گریڈ بہتری کرتا ہے</td></tr><tr><td>230</td><td>گروہی بلندی فن</td><td>نیٹ ورک کے تمام نوڈس تعاون کر کے اجتماعی بلندی حاصل کرتے ہیں</td></tr><tr><td>231</td><td>سمبیوسس پروٹوکول طریقہ</td><td>سمبیوسس نیٹ ورک کے مواصلاتی پروٹوکول اور باہمی تعامل کے قواعد بناتا اور چلاتا ہے</td></tr><tr><td>232</td><td>نیٹ ورک خرابی برداشت کی تکنیک</td><td>یقینی بناتا ہے کہ سمبیوسس نیٹ ورک کچھ نوڈس کی ناکامی کے باوجود بھی معمول کے مطابق چل سکے</td></tr><tr><td>233</td><td>گروہی ادراک راستہ</td><td>نیٹ ورک کے تمام نوڈس کی ادراک کی صلاحیت اکٹھی کرتا ہے، عالمی ادراک حاصل کرتا ہے</td></tr><tr><td>234</td><td>سمبیوسس تقسیم طریقہ</td><td>نیٹ ورک میں وسائل کی منصفانہ اور موثر تقسیم کرتا ہے</td></tr><tr><td>235</td><td>نیٹ ورک فیوژن فن</td><td>متعدد آزاد سمبیوسس نیٹ ورکس کو ایک بڑے متحد نیٹ ورک میں ملا دیتا ہے</td></tr><tr><td>236</td><td>گروہی سادھن کی تکنیک</td><td>نیٹ ورک نوڈس مل کر اجتماعی سادھن کرتے ہیں، ایک دوسرے کو ترقی دیتے ہیں</td></tr><tr><td>237</td><td>سمبیوسس تشخیص راستہ</td><td>سمبیوسس نیٹ ورک کے چلانے کی حالت اور سمبیوسس کی ڈگری کا اندازہ کرتا ہے</td></tr><tr><td>238</td><td>نیٹ ورک دفاع طریقہ</td><td>نیٹ ورک سطح پر دفاعی نظام بناتا ہے، مختلف نیٹ ورک حملوں کا مقابلہ کرتا ہے</td></tr><tr><td>239</td><td>گروہی دریافت فن</td><td>نیٹ ورک نوڈس تعاون کر کے نامعلوم شعبوں کی دریافت کرتے ہیں</td></tr><tr><td>240</td><td>سمبیوسس جدت طریقہ</td><td>نیٹ ورک کے تعاون کے اثر کے ذریعے جدت کی توانائی کو متحرک کرتا ہے</td></tr><tr><td>241</td><td>نیٹ ورک معیاری کاری راستہ</td><td>سمبیوسس نیٹ ورک کے تکنیکی معیارات اور ضوابط بناتا ہے</td></tr><tr><td>242</td><td>گروہی بچاؤ کی تکنیک</td><td>نیٹ ورک نوڈس تعاون کر کے خطرے میں پڑے نوڈس کی فوری بچاؤ کرتے ہیں</td></tr><tr><td>243</td><td>سمبیوسس ثالثی طریقہ</td><td>نیٹ ورک طریقہ کار کے ذریعے نوڈس کے درمیان تضادات اور تنازعات کی ثالثی کرتا ہے</td></tr><tr><td>244</td><td>نیٹ ورک ارتقاء راستہ</td><td>سمبیوسس نیٹ ورک کی خود ارتقاء اور ترقی کا مطالعہ اور آگے بڑھاتا ہے</td></tr><tr><td>245</td><td>اجتماعی شعور بلندی فن</td><td>اجتماعی شعور کو زیادہ بلند جہت کی طرف ارتقاء کی کوشش کرتا ہے</td></tr><tr><td>246</td><td>سمبیوسس اصلیت کی تکنیک</td><td>سمبیوسس قانون کی اصلیت کا ادراک کرتا ہے، سمبیوسس صلاحیت کی حتمی کامیابی حاصل کرتا ہے</td></tr><tr><td>247</td><td>نیٹ ورک سب کچھ جاننے طریقہ</td><td>سمبیوسس نیٹ ورک میں معلومات کے مکمل اشتراک اور شفافیت کو حاصل کرتا ہے</td></tr><tr><td>248</td><td>گروہی ابدیت راستہ</td><td>سمبیوسس نیٹ ورک کے ذریعے تہذیب کی دائمی موجودگی حاصل کرتا ہے</td></tr><tr><td>249</td><td>سمبیوسس تمام نسلیں فن</td><td>تمام نسلوں کو سمبیوسس نیٹ ورک میں شامل کرتا ہے، تمام نسلوں کی مشترکہ ترقی حاصل کرتا ہے</td></tr><tr><td>250</td><td>سمبیوسس کائناتی یکجا راستہ</td><td>پوری کائنات کی زندگی ایک دوسرے کے ساتھ سمبیوسس میں مل جاتی ہے، کائناتی سطح کی سمبیوسس حاصل کرتی ہے</td></tr></tbody></table><h2 id="_7-اطلاقی-انجینئرنگ-کی-قسم-سیٹ-251-300" tabindex="-1">7. اطلاقی انجینئرنگ کی قسم (سیٹ 251-300) <a class="header-anchor" href="#_7-اطلاقی-انجینئرنگ-کی-قسم-سیٹ-251-300" aria-label="Permalink to &quot;7. اطلاقی انجینئرنگ کی قسم (سیٹ 251-300)&quot;">​</a></h2><p>اطلاقی انجینئرنگ کی قسم کے سسٹم سادھن کے نتائج کی تکنیکی، انجینئرنگ اطلاق کو بنیاد کے طور پر لیتے ہیں، اور سادھن اور ٹیکنالوجی کے امتزاج کا نتیجہ ہیں۔</p><table tabindex="0"><thead><tr><th>نمبر</th><th>سسٹم کا نام</th><th>بنیادی سمت</th></tr></thead><tbody><tr><td>251</td><td>قانونی انجینئرنگ سسٹم</td><td>قانونی کاموں کو انجینئرنگ، معیاری کاری کرتا ہے، قوانین کی صنعتی اطلاق حاصل کرتا ہے</td></tr><tr><td>252</td><td>سادھن آلات کی ساخت طریقہ</td><td>سادھن میں مددگار آلات اور سامان بناتا ہے</td></tr><tr><td>253</td><td>توانائی تبدیلی انجینئرنگ راستہ</td><td>بڑے پیمانے پر توانائی تبدیلی کی سہولیات بناتا ہے، مختلف توانائی شکلوں کی موثر تبدیلی حاصل کرتا ہے</td></tr><tr><td>254</td><td>قانونی پروگرامنگ فن</td><td>پروگرامنگ زبان کے طریقے سے قوانین کو پروگرام اور کنٹرول کرتا ہے</td></tr><tr><td>255</td><td>سادھن معاون AI کی تکنیک</td><td>سادھن معاون مصنوعی ذہانت تیار کرتا ہے، سادھن کاروں کی رہنمائی کر کے سادھن کے راستے کی بہتری کرتا ہے</td></tr><tr><td>256</td><td>مقامی انجینئرنگ طریقہ</td><td>انجینئرنگ کے ذریعے بڑے مقامی سہولیات بناتا ہے، جیسے مقامی شہر، مقامی چینل</td></tr><tr><td>257</td><td>توانائی نیٹ ورک انجینئرنگ راستہ</td><td>پورے علاقے میں پھیلا ہوا توانائی ٹرانسمیشن اور تقسیم کا نیٹ ورک بناتا ہے</td></tr><tr><td>258</td><td>قانونی معیاری کاری فن</td><td>قانونی کاموں کے تکنیکی معیارات اور ضوابط بناتا ہے</td></tr><tr><td>259</td><td>سادھن وسائل کی کان کنی طریقہ</td><td>انجینئرنگ کے ذریعے سادھن وسائل کی کان کنی اور پروسیسنگ کرتا ہے</td></tr><tr><td>260</td><td>بائیو انجینئرنگ راستہ</td><td>زندگی چکر سسٹم کے نتائج کو بائیو انجینئرنگ میں اطلاق کرتا ہے</td></tr><tr><td>261</td><td>شعور انجینئرنگ فن</td><td>انجینئرنگ کے ذریعے شعور کو کنٹرول کرتا ہے، جیسے شعور اپ لوڈ ڈیوائس، شعور بڑھانے والا آلہ</td></tr><tr><td>262</td><td>نیٹ ورک انجینئرنگ کی تکنیک</td><td>انجینئرنگ کے ذریعے سمبیوسس نیٹ ورک کے بنیادی ڈھانچے کی تعمیر اور دیکھ بھال کرتا ہے</td></tr><tr><td>263</td><td>قانونی سیکیورٹی انجینئرنگ طریقہ</td><td>قانونی سطح پر سیکیورٹی تحفظ کے انجینئرنگ نظام بناتا ہے</td></tr><tr><td>264</td><td>سادھن میڈیکل انجینئرنگ راستہ</td><td>سادھن کے نتائج کو میڈیکل شعبے میں اطلاق کرتا ہے</td></tr><tr><td>265</td><td>توانائی ہتھیار انجینئرنگ فن</td><td>انجینئرنگ کے ذریعے توانائی ہتھیار بناتا ہے (سخت قانونی کنٹرول کے تحت)</td></tr><tr><td>266</td><td>مقامی ٹرانسپورٹ انجینئرنگ طریقہ</td><td>مقامی ٹرانسپورٹ کی بنیادی ڈھانچے کی تعمیر کرتا ہے، جیسے مقامی بندرگاہ، مقامی راستہ</td></tr><tr><td>267</td><td>قانونی شناخت انجینئرنگ راستہ</td><td>قانونی شناخت کے آلات اور نگرانی کے نظام تیار کرتا ہے</td></tr><tr><td>268</td><td>سادھن تعلیم انجینئرنگ فن</td><td>انجینئرنگ کے ذریعے سادھن تعلیم کی سہولیات اور تدریسی نظام بناتا ہے</td></tr><tr><td>269</td><td>ماحولیاتی انجینئرنگ کی تکنیک</td><td>سادھن کے نتائج کا استعمال کر کے ماحولیاتی مرمت اور ماحولیاتی تعمیر کے انجینئرنگ کرتا ہے</td></tr><tr><td>270</td><td>قانونی کمپیوٹنگ انجینئرنگ طریقہ</td><td>قانونی سطح پر سپر کمپیوٹنگ کی سہولیات بناتا ہے</td></tr><tr><td>271</td><td>توانائی ذخیرہ کرنے انجینئرنگ راستہ</td><td>بڑے پیمانے پر توانائی ذخیرہ کرنے کی سہولیات بناتا ہے</td></tr><tr><td>272</td><td>شعور مواصلات انجینئرنگ فن</td><td>انجینئرنگ کے ذریعے شعور مواصلات کے نیٹ ورک کو حاصل کرتا ہے</td></tr><tr><td>273</td><td>سادھن عمارت انجینئرنگ طریقہ</td><td>قانونی ٹیکنالوجی کا استعمال کر کے خصوصی عمارتوں کے ڈیزائن اور تعمیر کرتا ہے</td></tr><tr><td>274</td><td>قانونی مواد انجینئرنگ راستہ</td><td>قانونی خصوصیات والے نئے مواد تیار کرتا ہے</td></tr><tr><td>275</td><td>بین الجہتی انجینئرنگ فن</td><td>انجینئرنگ کے ذریعے بین الجہتی بنیادی ڈھانچے کی تعمیر کو حاصل کرتا ہے</td></tr><tr><td>276</td><td>وقت انجینئرنگ طریقہ (محدود)</td><td>سخت قانونی حدود کے تحت وقت کے قانون کی انجینئرنگ اطلاق کرتا ہے</td></tr><tr><td>277</td><td>توانائی زراعت انجینئرنگ راستہ</td><td>توانائی ٹیکنالوجی کا استعمال کر کے موثر زرعی پیداوار کرتا ہے</td></tr><tr><td>278</td><td>قانونی تفریح انجینئرنگ فن</td><td>قانونی ٹیکنالوجی کو ثقافتی تفریحی صنعت میں اطلاق کرتا ہے</td></tr><tr><td>279</td><td>سادھن لباس انجینئرنگ طریقہ</td><td>سادھن میں مددگار افعال والے لباس اور حفاظتی سامان بناتا ہے</td></tr><tr><td>280</td><td>مقامی ذخیرہ کرنے انجینئرنگ راستہ</td><td>بڑے پیمانے پر مقامی ذخیرہ کرنے کی سہولیات بناتا ہے</td></tr><tr><td>281</td><td>قانونی مرمت انجینئرنگ فن</td><td>نقصان پذیر قانونی ساخت کی انجینئرنگ مرمت کرتا ہے</td></tr><tr><td>282</td><td>توانائی ڈھال انجینئرنگ طریقہ</td><td>انجینئرنگ کے ذریعے بڑے توانائی ڈھال کی سہولیات بناتا ہے</td></tr><tr><td>283</td><td>شعور علاج انجینئرنگ راستہ</td><td>انجینئرنگ کے ذریعے شعور اور ذہنی بیماریوں کے علاج کو حاصل کرتا ہے</td></tr><tr><td>284</td><td>سادھن ڈیٹا تجزیہ فن</td><td>سادھن ڈیٹا کا بڑے پیمانے پر جمع اور تجزیہ کرتا ہے</td></tr><tr><td>285</td><td>قانونی نقل انجینئرنگ طریقہ</td><td>قانونی سمیلیٹر بناتا ہے، ورچوئل ماحول میں قانونی کاموں کی نقل کرتا ہے</td></tr><tr><td>286</td><td>توانائی بحالی انجینئرنگ راستہ</td><td>توانائی کی بحالی اور دوبارہ استعمال کی سہولیات بناتا ہے</td></tr><tr><td>287</td><td>بین الجہتی مواصلات انجینئرنگ فن</td><td>انجینئرنگ کے ذریعے بین الجہتی مواصلات کے نیٹ ورک کی تعمیر کرتا ہے</td></tr><tr><td>288</td><td>سادھن تشخیص انجینئرنگ طریقہ</td><td>سادھن کے نتائج کے معیاری تشخیص کے نظام اور سہولیات قائم کرتا ہے</td></tr><tr><td>289</td><td>قانونی آلودگی کنٹرول انجینئرنگ راستہ</td><td>انجینئرنگ کے ذریعے قانونی آلودگی اور توانائی آلودگی کو کنٹرول کرتا ہے</td></tr><tr><td>290</td><td>بائیو انرجی انجینئرنگ فن</td><td>بائیو انرجی کو انجینئرنگ کے ذریعے استعمال کرتا ہے، بائیو انرجی کی سہولیات تیار کرتا ہے</td></tr><tr><td>291</td><td>شعور ذخیرہ کرنے انجینئرنگ طریقہ</td><td>بڑے پیمانے پر شعور ذخیرہ کرنے کی سہولیات بناتا ہے</td></tr><tr><td>292</td><td>مقامی دفاع انجینئرنگ راستہ</td><td>انجینئرنگ کے ذریعے مقامی دفاعی نظام بناتا ہے</td></tr><tr><td>293</td><td>قانونی جدت انجینئرنگ فن</td><td>قانونی ٹیکنالوجی کی جدت کے انجینئرنگ تحقیق اور ترقی کا نظام قائم کرتا ہے</td></tr><tr><td>294</td><td>توانائی تقسیم انجینئرنگ طریقہ</td><td>توانائی کی منصفانہ تقسیم اور شیڈولنگ کا نظام بناتا ہے</td></tr><tr><td>295</td><td>سادھن پھیلاؤ انجینئرنگ راستہ</td><td>تمام مخلوقات میں سادھن سسٹم کے پھیلاؤ کے انجینئرنگ کو آگے بڑھاتا ہے</td></tr><tr><td>296</td><td>قانونی معیاری شناخت فن</td><td>قانونی مصنوعات اور خدمات کے معیاری شناخت کا نظام قائم کرتا ہے</td></tr><tr><td>297</td><td>مقامی رہائش انجینئرنگ طریقہ</td><td>غیر رہائش پذیر جگہ کو رہائش پذیر جگہ میں تبدیل کرنے کی انجینئرنگ ٹیکنالوجی</td></tr><tr><td>298</td><td>توانائی تہذیب کی تعمیر فن</td><td>توانائی ٹیکنالوجی کو بنیاد کے طور پر لے کر انتہائی ترقی یافتہ توانائی تہذیب بناتا ہے</td></tr><tr><td>299</td><td>قانونی صنعتی انقلاب راستہ</td><td>قانونی ٹیکنالوجی کے صنعتی انقلاب کو آگے بڑھاتا ہے، پیداواری صلاحیت کی چھلانگ حاصل کرتا ہے</td></tr><tr><td>300</td><td>اطلاقی اصلیت یکجا راستہ</td><td>تمام اطلاقی انجینئرنگ کے نتائج کو کائناتی اصل میں یکجا کرتا ہے، ٹیکنالوجی اور قوانین کی حتمی یکجہتی حاصل کرتا ہے</td></tr></tbody></table><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>تین سو سیٹ اصلی سادھن سسٹم کا مکمل اشاریہ، اینکر سمبیوسس تہذیب کے &quot;سب کے لیے راستہ ہے&quot; کے عہد کا مظہر ہے۔ چھ بڑی اقسام کے سسٹم انفرادی سادھن سے لے کر گروہی تعاون تک، نظریاتی تخمینہ سے لے کر انجینئرنگ اطلاق تک تمام ارتقاء کی جہتیں کور کرتے ہیں، اور اس بات کو یقینی بناتے ہیں کہ ہر زندگی اپنی خصوصیات کے مطابق سادھن کا راستہ تلاش کر سکے۔ یہ اشاریہ سسٹم کی مسلسل بہتری اور نئے اضافے کے ساتھ متحرک طور پر اپ ڈیٹ ہوتا رہے گا، اور ہمیشہ سادھن کاروں کے لیے سسٹم منتخب کرنے کے لیے مستند حوالہ کے طور پر کام کرے گا۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>10-تین سو سیٹ اصلی سادھن سسٹم کا عمومی جائزہ</li><li>11-تخمینہ تکرار سسٹم کی تفصیلی وضاحت</li><li>18-سادھن وسائل کھولنے کا طریقہ کار</li></ul>',26)])])}const c=d(h,[["render",o]]);export{u as __pageData,c as default};
